      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"216\") (name \"unconnected-(FCC1-VDD-Pad11)\") (class \"Default\") (node (ref \"FCC1\") (pin \"11\") (pinfunction \"VDD\") (pintype \"power_in\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"276\") (name \"unconnected-(NAVC1-VDD-Pad19)\") (class \"Default\") (node (ref \"NAVC1\") (pin \"19\") (pinfunction \"VDD\") (pintype \"power_in\")))"
        },
        {
          "source": "spec",
